-- Additive source-bound storyboard still directions and private frame provenance.
-- CLI unavailable: reviewed named SQL follows repository native-MCP migrations.
-- No model activation, generation resume, provider calls or separate wallet.
begin;
alter table public.director_approvals add column storyboard_production_evidence jsonb;
create table public.director_storyboard_candidates(id uuid primary key,project_id uuid not null references public.director_projects(id),shot_id text not null check(shot_id~'^[A-Za-z0-9][A-Za-z0-9_-]{0,99}$'),spec_version integer not null check(spec_version between 1 and 100),asset_id uuid not null,asset_version integer not null check(asset_version>0),job_id uuid not null unique,created_at timestamptz not null default now(),foreign key(project_id,asset_id)references public.director_assets(project_id,id),foreign key(project_id,job_id)references public.director_jobs(project_id,id));
create index director_storyboard_candidates_project on public.director_storyboard_candidates(project_id);
alter table public.director_storyboard_candidates enable row level security;
create policy no_customer_access on public.director_storyboard_candidates for all to anon,authenticated using(false)with check(false);
revoke all on public.director_storyboard_candidates from public,anon,authenticated,service_role;grant select,insert on public.director_storyboard_candidates to service_role;
create trigger append_only before update or delete on public.director_storyboard_candidates for each row execute function public.director_reject_mutation();

create function public.director_storyboard_production_document_valid(d jsonb)returns boolean language plpgsql immutable security invoker set search_path=''as $$
declare k text;x jsonb;seen text[]:='{}';previous text:='';sortkey text;
begin
 if jsonb_typeof(d)is distinct from'object'or not(d ?&array['direction','visibleCharacterIds','aspectRatio','referenceBindings','referenceDecisions'])or octet_length(d::text)>150000 then return false;end if;
 for k in select jsonb_object_keys(d)loop if k not in('direction','visibleCharacterIds','aspectRatio','referenceBindings','referenceDecisions')then return false;end if;end loop;
 if jsonb_typeof(d->'direction')is distinct from'string'or length(btrim(d->>'direction'))not between 1 and 12000 or jsonb_typeof(d->'aspectRatio')is distinct from'string'or d->>'aspectRatio'not in('16:9','9:16','1:1')or jsonb_typeof(d->'visibleCharacterIds')is distinct from'array'or jsonb_array_length(d->'visibleCharacterIds')>30 or jsonb_typeof(d->'referenceBindings')is distinct from'array'or jsonb_array_length(d->'referenceBindings')>100 or jsonb_typeof(d->'referenceDecisions')is distinct from'array'or jsonb_array_length(d->'referenceDecisions')>30 then return false;end if;
 for x in select value from jsonb_array_elements(d->'visibleCharacterIds')loop if jsonb_typeof(x)is distinct from'string'or coalesce(x#>>'{}','')!~'^[A-Za-z][A-Za-z0-9_-]{0,79}$'or (x#>>'{}')collate"C"<=previous collate"C" then return false;end if;previous=x#>>'{}';end loop;
 previous='';for x in select value from jsonb_array_elements(d->'referenceBindings')loop
 if jsonb_typeof(x)is distinct from'object'or not(x ?&array['role','characterId','subjectId','subjectVersion','selectionVersion','assetId','assetVersion'])or jsonb_typeof(x->'role')is distinct from'string'or x->>'role'not in('identity','look','location')then return false;end if;for k in select jsonb_object_keys(x)loop if k not in('role','characterId','subjectId','subjectVersion','selectionVersion','assetId','assetVersion')then return false;end if;end loop;
 if x->>'role'='location'then if x->'characterId'is distinct from'null'::jsonb or coalesce(x->>'subjectId','')!~'^location:[A-Za-z][A-Za-z0-9_-]{0,79}$'then return false;end if;else if not(d->'visibleCharacterIds'@>jsonb_build_array(x->'characterId'))or x->>'subjectId'is distinct from(x->>'role')||':'||(x->>'characterId')then return false;end if;end if;
 foreach k in array array['subjectVersion','selectionVersion','assetVersion']loop if jsonb_typeof(x->k)is distinct from'number'or(x->>k)::numeric not between 1 and 9007199254740991 or(x->>k)::numeric<>trunc((x->>k)::numeric)then return false;end if;end loop;
 if coalesce(x->>'assetId','')!~'^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'then return false;end if;
 sortkey=(case x->>'role'when'identity'then'0'when'look'then'1'else'2'end)||coalesce(x->>'characterId','');if sortkey collate"C"<=previous collate"C"then return false;end if;previous=sortkey;
 end loop;
 for x in select value from jsonb_array_elements(d->'referenceDecisions')loop if jsonb_typeof(x)is distinct from'object'or not(x ?&array['requirementId','disposition','rationale'])or coalesce(x->>'requirementId','')!~'^[A-Za-z][A-Za-z0-9_-]{0,79}$'or x->>'requirementId'=any(seen)or jsonb_typeof(x->'disposition')is distinct from'string'or x->>'disposition'not in('bound','not_applicable','unresolved')or jsonb_typeof(x->'rationale')is distinct from'string'or length(btrim(x->>'rationale'))not between 1 and 2000 then return false;end if;seen=array_append(seen,x->>'requirementId');for k in select jsonb_object_keys(x)loop if k not in('requirementId','disposition','rationale')then return false;end if;end loop;end loop;return true;
exception when invalid_text_representation or numeric_value_out_of_range or invalid_parameter_value then return false;end $$;

create function public.director_storyboard_production_reference_assets(p_document jsonb,p_shot_id text,p_version integer)returns jsonb language sql immutable security invoker set search_path=''as $$
 select coalesce(jsonb_agg(jsonb_build_object('assetId',b->'assetId','assetVersion',b->'assetVersion')order by first_ordinal),'[]'::jsonb)from(select min(ordinality)first_ordinal,min(value::text)::jsonb b from jsonb_array_elements((select v.value->'document'->'referenceBindings'from jsonb_array_elements(p_document->'storyboardProduction'->'shots')r cross join lateral jsonb_array_elements(r.value->'versions')v where r.value->>'shotId'=p_shot_id and v.value->'version'=to_jsonb(p_version)))with ordinality group by value->'assetId',value->'assetVersion')bindings;
$$;
create function public.director_storyboard_production_pin_current(p_project_id uuid,p_document jsonb,b jsonb)returns boolean language plpgsql security invoker set search_path=''as $$
declare s jsonb;a public.director_artifacts;ap public.director_approvals;
begin
 select x.value into s from jsonb_array_elements(p_document->'referenceProduction'->'selections')with ordinality x(value,ordinality)where x.value->>'subjectId'=b->>'subjectId'order by x.ordinality desc limit 1;
 if s is null or s->'subjectVersion'is distinct from b->'subjectVersion'or s->'version'is distinct from b->'selectionVersion'or s->'assetId'is distinct from b->'assetId'or s->'assetVersion'is distinct from b->'assetVersion'or not public.director_reference_selection_current(p_project_id,p_document,b->>'subjectId',(b->>'selectionVersion')::integer)then return false;end if;
 select x.*into a from public.director_artifacts x where x.project_id=p_project_id and x.logical_key='reference_selection:'||(b->>'subjectId')and x.kind='reference_selection'and x.version=(b->>'selectionVersion')::integer;if a.id is null or a.content is distinct from s then return false;end if;
 select x.*into ap from public.director_approvals x where x.project_id=p_project_id and x.artifact_id=a.id order by x.ordinal desc limit 1;
 return coalesce(ap.decision='approved'and ap.reference_evidence->'acknowledgeReferenceReview'='true'::jsonb and ap.actor_id=(select p.owner_id from public.director_projects p where p.id=p_project_id),false);
exception when invalid_text_representation or numeric_value_out_of_range or invalid_parameter_value then return false;end $$;

create function public.director_storyboard_production_spec_current(p_project_id uuid,p_document jsonb,p_shot_id text,p_version integer)returns boolean language plpgsql security invoker set search_path=''as $$
declare r jsonb;s jsonb;c jsonb;d jsonb;sequence jsonb;b jsonb;requirement jsonb;decision jsonb;character jsonb;n integer;i integer:=0;expected_count integer;ap jsonb;aspect text;seen text[]:='{}';
begin
 if not public.director_current_storyboard_handoff_approved(p_project_id)or jsonb_typeof(p_document->'storyboardHandoff'->'shots')is distinct from'array'then return false;end if;
 select count(*),min(x.value::text)::jsonb into n,r from jsonb_array_elements(p_document->'storyboardProduction'->'shots')x where x.value->>'shotId'=p_shot_id;if n<>1 or r->'currentVersion'is distinct from to_jsonb(p_version)then return false;end if;
 select x.value into s from jsonb_array_elements(r->'versions')x where x.value->'version'=to_jsonb(p_version);d=s->'document';if not public.director_storyboard_production_document_valid(d)or jsonb_typeof(s->'contractVersion')is distinct from'number'or(s->>'contractVersion')::numeric<>trunc((s->>'contractVersion')::numeric)or jsonb_typeof(s->'sourceVersion')is distinct from'number'or(s->>'sourceVersion')::numeric<>trunc((s->>'sourceVersion')::numeric)or jsonb_typeof(s->'sequenceVersion')is distinct from'number'or(s->>'sequenceVersion')::numeric<>trunc((s->>'sequenceVersion')::numeric)then return false;end if;
 select v.value into c from jsonb_array_elements(p_document->'storyboardHandoff'->'shots')x cross join lateral jsonb_array_elements(x.value->'versions')v where x.value->>'id'=p_shot_id and x.value->'currentVersion'=s->'contractVersion'and v.value->'version'=s->'contractVersion';
 if c is null or c->'sourceVersion'is distinct from s->'sourceVersion'or not public.director_storyboard_contract_current(p_document,p_shot_id,(s->>'contractVersion')::integer)then return false;end if;
 select x.value into sequence from jsonb_array_elements(p_document->'storyboardHandoff'->'sequences')x where x.value->'version'=s->'sequenceVersion';if not exists(select 1 from jsonb_array_elements(sequence->'shots')x where x.value->>'shotId'=p_shot_id and x.value->'version'=s->'contractVersion')then return false;end if;
 select x.value->'fields'->'aspectRatio'into ap from jsonb_array_elements(p_document->'creativeBrief'->'versions')x where x.value->'version'=p_document->'creativeBrief'->'currentVersion';aspect=btrim(ap->>'value');if (aspect in('16:9','9:16','1:1')and d->>'aspectRatio'is distinct from aspect)or ap->>'status'='explicit'and aspect not in('16:9','9:16','1:1')then return false;end if;
 for character in select value from jsonb_array_elements(d->'visibleCharacterIds')loop if not(c->'document'->'characterIds'@>jsonb_build_array(character))then return false;end if;end loop;
 expected_count=2*jsonb_array_length(d->'visibleCharacterIds')+1;if jsonb_array_length(d->'referenceBindings')<>expected_count then return false;end if;
 for b in select value from jsonb_array_elements(d->'referenceBindings')loop if b->>'role'='location'and b->>'subjectId'is distinct from'location:'||(c->'document'->>'sceneId')then return false;end if;if not public.director_storyboard_production_pin_current(p_project_id,p_document,b)then return false;end if;end loop;
 -- Every pictured role needs both pins; no extra character association becomes visibility.
 for character in select value from jsonb_array_elements(d->'visibleCharacterIds')loop foreach aspect in array array['identity','look']loop if not exists(select 1 from jsonb_array_elements(d->'referenceBindings')x where x.value->>'role'=aspect and x.value->'characterId'=character)then return false;end if;end loop;end loop;
 if not exists(select 1 from jsonb_array_elements(d->'referenceBindings')x where x.value->>'role'='location')then return false;end if;
 if jsonb_array_length(d->'referenceDecisions')<>jsonb_array_length(c->'document'->'referenceRequirements')then return false;end if;
 for requirement in select value from jsonb_array_elements(c->'document'->'referenceRequirements')loop decision=d->'referenceDecisions'->i;i=i+1;if decision->'requirementId'is distinct from requirement->'id'or requirement->>'role'not in('identity','look','location')then return false;end if;if requirement->>'role'='location'then if decision->>'disposition'is distinct from'bound'then return false;end if;else select count(*)into n from jsonb_array_elements(d->'visibleCharacterIds')x where jsonb_array_length(requirement->'characterIds')=0 or requirement->'characterIds'@>jsonb_build_array(x.value);if n=0 then if decision->>'disposition'is distinct from'not_applicable'then return false;end if;elsif decision->>'disposition'is distinct from'bound'then return false;end if;end if;end loop;
 n=jsonb_array_length(public.director_storyboard_production_reference_assets(p_document,p_shot_id,p_version));return n between 1 and 10;
exception when invalid_text_representation or numeric_value_out_of_range or invalid_parameter_value then return false;end $$;

create function public.director_storyboard_production_direction_approved(p_project_id uuid,p_document jsonb,p_shot_id text,p_version integer)returns boolean language plpgsql security invoker set search_path=''as $$
declare a public.director_artifacts;ap public.director_approvals;s jsonb;
begin if not public.director_storyboard_production_spec_current(p_project_id,p_document,p_shot_id,p_version)then return false;end if;select v.value into s from jsonb_array_elements(p_document->'storyboardProduction'->'shots')r cross join lateral jsonb_array_elements(r.value->'versions')v where r.value->>'shotId'=p_shot_id and v.value->'version'=to_jsonb(p_version);select x.*into a from public.director_artifacts x where x.project_id=p_project_id and x.logical_key='storyboard_brief:'||p_shot_id and x.kind='storyboard_brief'and x.version=p_version;if a.id is null or a.content is distinct from jsonb_build_object('shotId',p_shot_id)||s then return false;end if;select x.*into ap from public.director_approvals x where x.project_id=p_project_id and x.artifact_id=a.id order by x.ordinal desc limit 1;return coalesce(ap.decision='approved'and ap.storyboard_production_evidence->'acknowledgeFrameDirection'='true'::jsonb and ap.actor_id=(select p.owner_id from public.director_projects p where p.id=p_project_id),false);end $$;
create function public.director_storyboard_production_candidate_valid(p_project_id uuid,p_candidate_id uuid,p_shot_id text,p_version integer,p_asset_id uuid,p_asset_version integer)returns boolean language sql security invoker set search_path=''as $$
 select exists(select 1 from public.director_storyboard_candidates c join public.director_assets a on a.project_id=c.project_id and a.id=c.asset_id where c.project_id=p_project_id and c.id=p_candidate_id and c.shot_id=p_shot_id and c.spec_version=p_version and c.asset_id=p_asset_id and c.asset_version=p_asset_version and a.metadata->'version'=to_jsonb(p_asset_version)and a.metadata->>'mime'='image/png'and a.metadata->>'bucket'='director-reference-media'and a.metadata->>'role'='storyboard_frame'and a.metadata->>'scope'='shot'and a.metadata->>'shotId'=p_shot_id);
$$;
create function public.director_storyboard_production_selection_current(p_project_id uuid,p_document jsonb,p_shot_id text,p_version integer)returns boolean language plpgsql security invoker set search_path=''as $$
declare s jsonb;r jsonb;
begin select x.value into s from jsonb_array_elements(p_document->'storyboardProduction'->'selections')with ordinality x(value,ordinality)where x.value->>'shotId'=p_shot_id order by x.ordinality desc limit 1;select x.value into r from jsonb_array_elements(p_document->'storyboardProduction'->'shots')x where x.value->>'shotId'=p_shot_id;return coalesce(s->'version'=to_jsonb(p_version)and s->'specVersion'=r->'currentVersion'and s->'review'->'criteriaAcknowledged'='true'::jsonb and public.director_storyboard_production_direction_approved(p_project_id,p_document,p_shot_id,(s->>'specVersion')::integer)and public.director_storyboard_production_candidate_valid(p_project_id,(s->>'candidateId')::uuid,p_shot_id,(s->>'specVersion')::integer,(s->>'assetId')::uuid,(s->>'assetVersion')::integer),false);exception when invalid_text_representation or numeric_value_out_of_range or invalid_parameter_value then return false;end $$;

-- Preserve every older currentness branch. Only the new frame artifacts use these rules.
do $$declare definition text;anchor text:='public.director_artifact_is_current(';begin definition=pg_get_functiondef('public.director_artifact_is_current(uuid,uuid)'::regprocedure);if(length(definition)-length(replace(definition,anchor,'')))/length(anchor)<>1 then raise exception'storyboard_production_artifact_baseline_mismatch';end if;execute replace(definition,anchor,'public.director_storyboard_production_legacy_artifact_current(');end $$;
create or replace function public.director_artifact_is_current(p_project_id uuid,p_artifact_id uuid)returns boolean language plpgsql security invoker set search_path=''as $$
declare a public.director_artifacts;d jsonb;s jsonb;
begin select x.*into a from public.director_artifacts x where x.project_id=p_project_id and x.id=p_artifact_id;if a.id is null then return false;end if;if a.kind in('storyboard_brief','storyboard_frame')or left(a.logical_key,17)in('storyboard_brief:','storyboard_frame:')then select p.brief into d from public.director_projects p where p.id=p_project_id;if a.kind='storyboard_brief'and left(a.logical_key,17)='storyboard_brief:'then select v.value into s from jsonb_array_elements(d->'storyboardProduction'->'shots')r cross join lateral jsonb_array_elements(r.value->'versions')v where r.value->>'shotId'=substr(a.logical_key,18)and v.value->'version'=to_jsonb(a.version);return coalesce(public.director_storyboard_production_spec_current(p_project_id,d,substr(a.logical_key,18),a.version)and a.content=jsonb_build_object('shotId',substr(a.logical_key,18))||s,false);elsif a.kind='storyboard_frame'and left(a.logical_key,17)='storyboard_frame:'then select x.value into s from jsonb_array_elements(d->'storyboardProduction'->'selections')x where x.value->'version'=to_jsonb(a.version);return coalesce(public.director_storyboard_production_selection_current(p_project_id,d,substr(a.logical_key,18),a.version)and a.content=s,false);end if;return false;end if;return public.director_storyboard_production_legacy_artifact_current(p_project_id,p_artifact_id);exception when invalid_text_representation or numeric_value_out_of_range or invalid_parameter_value then return false;end $$;
create function public.director_storyboard_production_review_guard()returns trigger language plpgsql security invoker set search_path=''as $$
declare p public.director_projects;a public.director_artifacts;
begin select x.*into p from public.director_projects x where x.id=new.project_id for update;select x.*into a from public.director_artifacts x where x.id=new.artifact_id and x.project_id=p.id;if a.kind not in('storyboard_brief','storyboard_frame')then if new.storyboard_production_evidence is not null then raise exception'storyboard_production_evidence_invalid';end if;return new;end if;if new.actor_id is distinct from p.owner_id then raise exception'not_project_owner';end if;if new.decision='approved'and(new.storyboard_production_evidence->'projectVersion'is distinct from p.brief->'version'or new.storyboard_production_evidence->>'archiveHash'is distinct from encode(sha256(convert_to((p.brief->'storyboardProduction')::text,'UTF8')),'hex')or not public.director_artifact_is_current(p.id,a.id)or a.kind='storyboard_brief'and new.storyboard_production_evidence->'acknowledgeFrameDirection'is distinct from'true'::jsonb or a.kind='storyboard_frame'and new.storyboard_production_evidence->'acknowledgeFrameReview'is distinct from'true'::jsonb)then raise exception'storyboard_production_review_required';end if;return new;end $$;
create trigger storyboard_production_review_guard before insert on public.director_approvals for each row execute function public.director_storyboard_production_review_guard();
create function public.director_approve_storyboard_production(p_actor_id uuid,p_project_id uuid,p_expected_version integer,p_artifact_id text,p_artifact_version integer,p_ack_frame_direction boolean,p_ack_frame_review boolean,p_decision text)returns jsonb language plpgsql security invoker set search_path=''as $$
declare p public.director_projects;a public.director_artifacts;ap public.director_approvals;e jsonb;
begin select x.*into p from public.director_projects x where x.id=p_project_id for update;if p.id is null or p_actor_id is null or p.owner_id is distinct from p_actor_id then raise exception'not_project_owner';end if;if p_decision is null or p_decision not in('approved','rejected','revoked')or p_artifact_version is null or p_artifact_version<1 then raise exception'storyboard_production_review_invalid';end if;if p_expected_version is null or p.brief->'version'is distinct from to_jsonb(p_expected_version)then raise exception'storyboard_production_review_stale';end if;select x.*into a from public.director_artifacts x where x.project_id=p.id and x.logical_key=p_artifact_id and x.version=p_artifact_version and x.kind in('storyboard_brief','storyboard_frame');if a.id is null then raise exception'storyboard_production_artifact_missing';end if;e=case when p_decision='approved'then jsonb_build_object('projectVersion',p_expected_version,'archiveHash',encode(sha256(convert_to((p.brief->'storyboardProduction')::text,'UTF8')),'hex'),'acknowledgeFrameDirection',p_ack_frame_direction,'acknowledgeFrameReview',p_ack_frame_review)else null end;insert into public.director_approvals(project_id,artifact_id,actor_id,decision,storyboard_production_evidence)values(p.id,a.id,p_actor_id,p_decision,e)returning*into ap;return jsonb_build_object('id',ap.id,'projectId',p.id,'artifactId',p_artifact_id,'version',p_artifact_version,'decision',p_decision,'actorId',p_actor_id,'createdAt',ap.created_at,'storyboardProduction',jsonb_build_object('frameDirectionAcknowledged',p_decision='approved'and p_ack_frame_direction,'frameReviewAcknowledged',p_decision='approved'and p_ack_frame_review));end $$;

create function public.director_storyboard_production_archive_guard()returns trigger language plpgsql security invoker set search_path=''as $$
begin if new.brief->'storyboardProduction'is distinct from old.brief->'storyboardProduction'and current_setting('director.storyboard_production_write',true)is distinct from new.id::text then raise exception'storyboard_production_guarded_save_required';end if;return new;end $$;
create trigger storyboard_production_archive_guard before update of brief on public.director_projects for each row execute function public.director_storyboard_production_archive_guard();
create function public.director_save_storyboard_production(p_actor_id uuid,p_project_id uuid,p_expected_version integer,p_expected_approval_id uuid,p_document jsonb,p_artifacts jsonb)returns void language plpgsql security invoker set search_path=''as $$
declare p public.director_projects;latest uuid;archive jsonb:=p_document->'storyboardProduction';old_archive jsonb;r jsonb;old_r jsonb;s jsonb;selection jsonb;c jsonb;sequence jsonb;n integer;i integer;ordinal integer;k text;previous text;
begin
 select x.*into p from public.director_projects x where x.id=p_project_id for update;if p.id is null or p_actor_id is null or p.owner_id is distinct from p_actor_id then raise exception'not_project_owner';end if;if p_expected_version is null or p.brief->'version'is distinct from to_jsonb(p_expected_version)or p_document->'version'is distinct from to_jsonb(p_expected_version+1)then raise exception'storyboard_production_save_stale';end if;select a.id into latest from public.director_approvals a where a.project_id=p.id order by a.ordinal desc limit 1;if latest is distinct from p_expected_approval_id then raise exception'storyboard_production_approval_changed';end if;
 if not public.director_current_storyboard_handoff_approved(p.id)or p_document-'storyboardProduction'-'version'is distinct from p.brief-'storyboardProduction'-'version'or jsonb_typeof(archive)is distinct from'object'or octet_length(archive::text)>3500000 or jsonb_typeof(archive->'shots')is distinct from'array'or jsonb_array_length(archive->'shots')not between 1 and 200 or jsonb_typeof(archive->'selections')is distinct from'array'or jsonb_array_length(archive->'selections')>1000 then raise exception'storyboard_production_save_scope_invalid';end if;for k in select jsonb_object_keys(archive)loop if k not in('shots','selections')then raise exception'storyboard_production_save_scope_invalid';end if;end loop;old_archive=p.brief->'storyboardProduction';
 for i in 0..coalesce(jsonb_array_length(old_archive->'selections'),0)-1 loop if archive->'selections'->i is distinct from old_archive->'selections'->i then raise exception'storyboard_production_history_invalid';end if;end loop;
 for old_r in select value from jsonb_array_elements(coalesce(old_archive->'shots','[]'::jsonb))loop select x.value into r from jsonb_array_elements(archive->'shots')x where x.value->'shotId'=old_r->'shotId';if r is null then raise exception'storyboard_production_history_invalid';end if;for i in 0..jsonb_array_length(old_r->'versions')-1 loop if r->'versions'->i is distinct from old_r->'versions'->i then raise exception'storyboard_production_history_invalid';end if;end loop;end loop;
 for r in select value from jsonb_array_elements(archive->'shots')loop if coalesce(r->>'shotId','')!~'^[A-Za-z0-9][A-Za-z0-9_-]{0,99}$'or jsonb_typeof(r->'versions')is distinct from'array'or jsonb_array_length(r->'versions')not between 1 and 100 or r->'currentVersion'is distinct from to_jsonb(jsonb_array_length(r->'versions'))then raise exception'storyboard_production_spec_invalid';end if;for k in select jsonb_object_keys(r)loop if k not in('shotId','currentVersion','versions')then raise exception'storyboard_production_spec_invalid';end if;end loop;select count(*)into n from jsonb_array_elements(archive->'shots')x where x.value->'shotId'=r->'shotId';if n<>1 then raise exception'storyboard_production_spec_invalid';end if;
 ordinal=0;for s in select value from jsonb_array_elements(r->'versions')loop ordinal=ordinal+1;if s->'version'is distinct from to_jsonb(ordinal)or not public.director_storyboard_production_document_valid(s->'document')or jsonb_typeof(s->'createdAt')is distinct from'string'or coalesce(s->>'createdAt','')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{3}Z$'or to_char((s->>'createdAt')::timestamptz at time zone'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')is distinct from s->>'createdAt'then raise exception'storyboard_production_spec_invalid';end if;for k in select jsonb_object_keys(s)loop if k not in('version','contractVersion','sourceVersion','sequenceVersion','document','createdAt')then raise exception'storyboard_production_spec_invalid';end if;end loop;foreach k in array array['contractVersion','sourceVersion','sequenceVersion']loop if jsonb_typeof(s->k)is distinct from'number'or(s->>k)::numeric not between 1 and 9007199254740991 or(s->>k)::numeric<>trunc((s->>k)::numeric)then raise exception'storyboard_production_spec_invalid';end if;end loop;
 select v.value into c from jsonb_array_elements(p_document->'storyboardHandoff'->'shots')x cross join lateral jsonb_array_elements(x.value->'versions')v where x.value->'id'=r->'shotId'and v.value->'version'=s->'contractVersion';select x.value into sequence from jsonb_array_elements(p_document->'storyboardHandoff'->'sequences')x where x.value->'version'=s->'sequenceVersion';if c is null or c->'sourceVersion'is distinct from s->'sourceVersion'or not exists(select 1 from jsonb_array_elements(sequence->'shots')x where x.value->'shotId'=r->'shotId'and x.value->'version'=s->'contractVersion')then raise exception'storyboard_production_spec_invalid';end if;end loop;end loop;
 i=0;for selection in select value from jsonb_array_elements(archive->'selections')loop i=i+1;if selection->'version'is distinct from to_jsonb(i)or jsonb_typeof(selection)is distinct from'object'or not(selection ?&array['version','shotId','specVersion','candidateId','assetId','assetVersion','review','createdAt'])or selection->'review'is distinct from'{"criteriaAcknowledged":true}'::jsonb or coalesce(selection->>'createdAt','')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{3}Z$'or to_char((selection->>'createdAt')::timestamptz at time zone'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')is distinct from selection->>'createdAt'then raise exception'storyboard_production_selection_invalid';end if;for k in select jsonb_object_keys(selection)loop if k not in('version','shotId','specVersion','candidateId','assetId','assetVersion','review','createdAt')then raise exception'storyboard_production_selection_invalid';end if;end loop;foreach k in array array['specVersion','assetVersion']loop if jsonb_typeof(selection->k)is distinct from'number'or(selection->>k)::numeric<1 or(selection->>k)::numeric<>trunc((selection->>k)::numeric)then raise exception'storyboard_production_selection_invalid';end if;end loop;if i>coalesce(jsonb_array_length(old_archive->'selections'),0)and not public.director_storyboard_production_selection_current(p.id,p_document,selection->>'shotId',i)then raise exception'storyboard_production_selection_invalid';end if;end loop;
 previous=current_setting('director.storyboard_production_write',true);perform set_config('director.storyboard_production_write',p.id::text,true);perform public.director_save_project(p_actor_id,p_project_id,p_expected_version,p_document,p_artifacts);perform set_config('director.storyboard_production_write',coalesce(previous,''),true);
end $$;

create function public.director_storyboard_production_candidate_guard()returns trigger language plpgsql security invoker set search_path=''as $$
declare p public.director_projects;a public.director_assets;j public.director_jobs;q public.director_proposals;s jsonb;endpoint text;g jsonb;width integer;height integer;
begin select x.*into p from public.director_projects x where x.id=new.project_id for update;select x.*into a from public.director_assets x where x.id=new.asset_id and x.project_id=p.id for update;select v.value into s from jsonb_array_elements(p.brief->'storyboardProduction'->'shots')r cross join lateral jsonb_array_elements(r.value->'versions')v where r.value->>'shotId'=new.shot_id and v.value->'version'=to_jsonb(new.spec_version);width=case s->'document'->>'aspectRatio'when'16:9'then 1536 when'9:16'then 864 when'1:1'then 1024 end;height=case s->'document'->>'aspectRatio'when'16:9'then 864 when'9:16'then 1536 when'1:1'then 1024 end;
 if s is null or a.id is null or a.metadata->>'id'is distinct from a.id::text or a.metadata->>'projectId'is distinct from p.id::text or a.metadata->>'storageKey'is distinct from a.storage_key or left(a.storage_key,length(p.owner_id::text||'/'||p.id::text||'/'))is distinct from p.owner_id::text||'/'||p.id::text||'/'or a.metadata->'version'is distinct from to_jsonb(new.asset_version)or a.metadata->>'mime'is distinct from'image/png'or a.metadata->>'bucket'is distinct from'director-reference-media'or a.metadata->>'role'is distinct from'storyboard_frame'or a.metadata->>'scope'is distinct from'shot'or a.metadata->>'shotId'is distinct from new.shot_id or a.metadata->'width'is distinct from to_jsonb(width)or a.metadata->'height'is distinct from to_jsonb(height)or coalesce(a.metadata->>'checksum','')!~'^[a-f0-9]{64}$'or jsonb_typeof(a.metadata->'size')is distinct from'number'or(a.metadata->>'size')::numeric not between 1 and 10485760 or(a.metadata->>'size')::numeric<>trunc((a.metadata->>'size')::numeric)then raise exception'storyboard_production_candidate_asset_invalid';end if;
 select x.*into j from public.director_jobs x where x.id=new.job_id and x.project_id=p.id;select x.*into q from public.director_proposals x where x.id=j.proposal_id and x.project_id=p.id;select x.registry_snapshot->>'endpoint'into endpoint from public.director_quote_records x where x.proposal_id=q.id and x.project_id=p.id;g=a.metadata->'generated';
 if j.id is null or j.status is distinct from'completed'or j.provider_request_id is null or q.id is null or q.payload_hash is distinct from j.payload_hash or not exists(select 1 from public.director_artifacts ar where ar.project_id=p.id and ar.id=q.artifact_id and ar.kind='storyboard_brief'and ar.logical_key='storyboard_brief:'||new.shot_id and ar.version=new.spec_version)or g is distinct from jsonb_build_object('kind','storyboard_frame','jobId',j.id,'requestId',j.provider_request_id,'endpoint',endpoint,'payloadHash',j.payload_hash,'shotId',new.shot_id,'specVersion',new.spec_version)or not exists(select 1 from public.director_audit_events e where e.project_id=p.id and e.event_type='job_provider_output'and e.details->>'job_id'=j.id::text and jsonb_typeof(e.details->'output'->'images')='array'and jsonb_array_length(e.details->'output'->'images')=1 and e.details->'output'->'images'->0->>'url'~'^https://([A-Za-z0-9-]+\.)*fal\.media/')then raise exception'storyboard_production_generated_provenance_invalid';end if;return new;end $$;
create trigger storyboard_production_candidate_guard before insert on public.director_storyboard_candidates for each row execute function public.director_storyboard_production_candidate_guard();
create function public.director_storyboard_production_asset_guard()returns trigger language plpgsql security invoker set search_path=''as $$
declare k text;begin if not exists(select 1 from public.director_storyboard_candidates c where c.asset_id=old.id and c.project_id=old.project_id)then if TG_OP='DELETE'then return old;end if;return new;end if;if TG_OP='DELETE'then raise exception'storyboard_production_asset_immutable';end if;if new.project_id is distinct from old.project_id or new.kind is distinct from old.kind or new.storage_key is distinct from old.storage_key then raise exception'storyboard_production_asset_immutable';end if;foreach k in array array['id','projectId','storageKey','version','mime','role','scope','shotId','checksum','size','bucket','generated','width','height']loop if new.metadata->k is distinct from old.metadata->k then raise exception'storyboard_production_asset_immutable';end if;end loop;return new;end $$;
create trigger storyboard_production_asset_guard before update or delete on public.director_assets for each row execute function public.director_storyboard_production_asset_guard();
create function public.director_register_storyboard_candidate(p_actor_id uuid,p_project_id uuid,p_candidate jsonb)returns jsonb language plpgsql security invoker set search_path=''as $$
declare p public.director_projects;c public.director_storyboard_candidates;v public.director_storyboard_candidates;k text;
begin select x.*into p from public.director_projects x where x.id=p_project_id for update;if p.id is null or p_actor_id is null or p.owner_id is distinct from p_actor_id then raise exception'not_project_owner';end if;if p_candidate->>'projectId'is distinct from p.id::text or p_candidate->>'origin'is distinct from'generated'or jsonb_typeof(p_candidate->'specVersion')is distinct from'number'or(p_candidate->>'specVersion')::numeric<>trunc((p_candidate->>'specVersion')::numeric)or jsonb_typeof(p_candidate->'assetVersion')is distinct from'number'or(p_candidate->>'assetVersion')::numeric<>trunc((p_candidate->>'assetVersion')::numeric)then raise exception'storyboard_production_candidate_invalid';end if;for k in select jsonb_object_keys(p_candidate)loop if k not in('id','projectId','shotId','specVersion','assetId','assetVersion','origin','jobId','createdAt')then raise exception'storyboard_production_candidate_invalid';end if;end loop;v.id=(p_candidate->>'id')::uuid;v.project_id=p.id;v.shot_id=p_candidate->>'shotId';v.spec_version=(p_candidate->>'specVersion')::integer;v.asset_id=(p_candidate->>'assetId')::uuid;v.asset_version=(p_candidate->>'assetVersion')::integer;v.job_id=(p_candidate->>'jobId')::uuid;select x.*into c from public.director_storyboard_candidates x where x.id=v.id or x.job_id=v.job_id;if c.id is not null then if to_jsonb(c)-'created_at'is distinct from to_jsonb(v)-'created_at'then raise exception'storyboard_production_candidate_conflict';end if;else insert into public.director_storyboard_candidates(id,project_id,shot_id,spec_version,asset_id,asset_version,job_id)values(v.id,v.project_id,v.shot_id,v.spec_version,v.asset_id,v.asset_version,v.job_id)returning*into c;end if;return jsonb_build_object('id',c.id,'projectId',c.project_id,'shotId',c.shot_id,'specVersion',c.spec_version,'assetId',c.asset_id,'assetVersion',c.asset_version,'origin','generated','jobId',c.job_id,'createdAt',to_char(c.created_at at time zone'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'));end $$;

create function public.director_storyboard_production_tariff_valid(p_price jsonb)returns boolean language plpgsql immutable security invoker set search_path=''as $$
declare c jsonb;base_count integer:=0;input_count integer:=0;k text;seen text[]:='{}';n numeric;d numeric;
begin if jsonb_typeof(p_price->'tariff')is distinct from'object'then return false;end if;for k in select jsonb_object_keys(p_price->'tariff')loop if k not in('schemaVersion','version','components')then return false;end if;end loop;if p_price->'tariff'->'schemaVersion'is distinct from'1'::jsonb or p_price->'tariff'->>'version'is distinct from p_price->>'version'or jsonb_typeof(p_price->'tariff'->'components')is distinct from'array'or jsonb_array_length(p_price->'tariff'->'components')<>2 then return false;end if;
 for c in select value from jsonb_array_elements(p_price->'tariff'->'components')loop if coalesce(c->>'id','')!~'^[A-Za-z][A-Za-z0-9_-]{0,63}$'or c->>'id'=any(seen)or c->>'rounding'is distinct from'ceil'or jsonb_typeof(c->'rate'->'numeratorMicroUsd')is distinct from'number'or jsonb_typeof(c->'rate'->'denominatorUnits')is distinct from'number'then return false;end if;for k in select jsonb_object_keys(c)loop if k not in('id','unit','rate','minimumUnits','includedUnits','characterCounting','rounding')then return false;end if;end loop;for k in select jsonb_object_keys(c->'rate')loop if k not in('numeratorMicroUsd','denominatorUnits')then return false;end if;end loop;seen=array_append(seen,c->>'id');n=(c->'rate'->>'numeratorMicroUsd')::numeric;d=(c->'rate'->>'denominatorUnits')::numeric;if n not between 1 and 9007199254740991 or d not between 1 and 9007199254740991 or n<>trunc(n)or d<>trunc(d)then return false;end if;foreach k in array array['includedUnits','minimumUnits']loop if c ? k and(jsonb_typeof(c->k)is distinct from'number'or(c->>k)::numeric not between 0 and 9007199254740991 or(c->>k)::numeric<>trunc((c->>k)::numeric))then return false;end if;end loop;if c->>'unit'in('image','request')then base_count=base_count+1;if coalesce(c->'includedUnits','0'::jsonb)is distinct from'0'::jsonb or jsonb_typeof(coalesce(c->'minimumUnits','0'::jsonb))is distinct from'number'or coalesce((c->>'minimumUnits')::numeric,0)not between 0 and 1 then return false;end if;elsif c->>'unit'='input_image'then input_count=input_count+1;if c->'includedUnits'is distinct from'1'::jsonb or coalesce(c->'minimumUnits','0'::jsonb)is distinct from'0'::jsonb then return false;end if;else return false;end if;end loop;return base_count=1 and input_count=1;
exception when invalid_text_representation or numeric_value_out_of_range or invalid_parameter_value then return false;end $$;
-- Add input-image arithmetic without changing existing rational rounding/units.
do $$declare definition text;anchor text:='elsif c->>''unit''=''second'' then';begin definition=pg_get_functiondef('public.director_composite_quote_valid(jsonb,jsonb,jsonb)'::regprocedure);if(length(definition)-length(replace(definition,anchor,'')))/length(anchor)<>1 then raise exception'storyboard_production_tariff_baseline_mismatch';end if;execute replace(definition,anchor,'elsif c->>''unit''=''input_image'' then
 if jsonb_typeof(p_payload->''image_urls'')is distinct from''array''or jsonb_array_length(p_payload->''image_urls'')not between 1 and 10 or exists(select 1 from jsonb_array_elements(p_payload->''image_urls'')x where jsonb_typeof(x.value)is distinct from''string''or coalesce(x.value#>>''{}'','''')!~''^https://[^/@[:space:]]+(/[^[:space:]]*)?$'')then return false;end if;raw=jsonb_array_length(p_payload->''image_urls'');
 '||anchor);end $$;
-- Publication remains evidence-reviewed; these are endpoint/task capabilities,
-- not activation or assertions that any candidate price/quality is verified.
do $$declare definition text;anchor text;replacement text;begin
 definition=pg_get_functiondef('public.director_registry_review_ready(text,jsonb,jsonb)'::regprocedure);
 anchor='p_profile->>''endpoint'' not in(''minimax/h3-max/reference-to-video'',''elevenlabs/tts/eleven-v4'',''bytedance/seedream/v5/pro/edit'')';if(length(definition)-length(replace(definition,anchor,'')))/length(anchor)<>1 then raise exception'storyboard_production_registry_endpoint_baseline_mismatch';end if;definition=replace(definition,anchor,'p_profile->>''endpoint'' not in(''minimax/h3-max/reference-to-video'',''elevenlabs/tts/eleven-v4'',''bytedance/seedream/v5/pro/edit'',''fal-ai/flux-2-pro'',''fal-ai/flux-2/klein/9b'')');
 anchor='if (item #>> ''{}'') is distinct from (case p_profile->>''endpoint'' when ''minimax/h3-max/reference-to-video'' then ''reference_video'' when ''elevenlabs/tts/eleven-v4'' then ''speech_synthesis'' when ''bytedance/seedream/v5/pro/edit'' then ''image_edit'' end) then return false;end if;';
 if(length(definition)-length(replace(definition,anchor,'')))/length(anchor)<>1 then raise exception'storyboard_production_registry_task_baseline_mismatch';end if;
 replacement='if not coalesce(case p_profile->>''endpoint''when''minimax/h3-max/reference-to-video''then item#>>''{}''=''reference_video''when''elevenlabs/tts/eleven-v4''then item#>>''{}''=''speech_synthesis''when''bytedance/seedream/v5/pro/edit''then item#>>''{}''in(''image_edit'',''reference_look'',''storyboard_frame'')when''fal-ai/flux-2-pro''then item#>>''{}''=''reference_image''when''fal-ai/flux-2/klein/9b''then item#>>''{}''=''reference_image''else false end,false)then return false;end if;if item#>>''{}''=''storyboard_frame''and not public.director_storyboard_production_tariff_valid(p)then return false;end if;';execute replace(definition,anchor,replacement);
end $$;

create function public.director_storyboard_production_quote_valid(p_project_id uuid,p_document jsonb,p_quote jsonb,p_payload jsonb,p_endpoint text)returns boolean language plpgsql security invoker set search_path=''as $$
declare r jsonb;s jsonb;expected jsonb;refs jsonb;ref jsonb;url text;a public.director_assets;n integer;i integer:=0;width integer;height integer;
begin
 if left(p_quote->>'artifactId',17)<>'storyboard_brief:'or p_quote->>'task'is distinct from'storyboard_frame'or p_endpoint is distinct from'bytedance/seedream/v5/pro/edit'then return false;end if;
 select x.value into r from jsonb_array_elements(p_document->'storyboardProduction'->'shots')x where 'storyboard_brief:'||(x.value->>'shotId')=p_quote->>'artifactId';select x.value into s from jsonb_array_elements(r->'versions')x where x.value->'version'=r->'currentVersion';
 if p_quote->'artifactVersion'is distinct from s->'version'or not public.director_storyboard_production_direction_approved(p_project_id,p_document,r->>'shotId',(s->>'version')::integer)or not public.director_storyboard_production_tariff_valid(p_quote->'priceEvidence')or not public.director_composite_quote_valid(p_quote,p_payload,p_quote->'priceEvidence')then return false;end if;
 refs=public.director_storyboard_production_reference_assets(p_document,r->>'shotId',(s->>'version')::integer);expected=jsonb_build_object('shotId',r->'shotId','specVersion',s->'version','snapshot',s,'sequenceVersion',p_document->'storyboardHandoff'->'sequences'->-1->'version','prompt',p_payload->'prompt','referenceAssets',refs);
 width=case s->'document'->>'aspectRatio'when'16:9'then 1536 when'9:16'then 864 when'1:1'then 1024 end;height=case s->'document'->>'aspectRatio'when'16:9'then 864 when'9:16'then 1536 when'1:1'then 1024 end;
 if p_quote->'storyboardBinding'is distinct from expected or jsonb_typeof(p_payload->'prompt')is distinct from'string'or length(btrim(p_payload->>'prompt'))<1 or p_payload->'image_size'is distinct from jsonb_build_object('width',width,'height',height)or p_payload->>'output_format'is distinct from'png'or p_payload->'num_images'is distinct from'1'::jsonb or p_payload->'sync_mode'is distinct from'false'::jsonb or p_payload->'enable_safety_checker'is distinct from'true'::jsonb or jsonb_typeof(p_payload->'image_urls')is distinct from'array'or jsonb_array_length(p_payload->'image_urls')<>jsonb_array_length(refs)then return false;end if;
 select count(distinct value)into n from jsonb_array_elements(p_payload->'image_urls');if n<>jsonb_array_length(refs)then return false;end if;
 for ref in select value from jsonb_array_elements(refs)loop select x.*into a from public.director_assets x where x.project_id=p_project_id and x.id=(ref->>'assetId')::uuid and x.metadata->'version'=ref->'assetVersion';url=p_payload->'image_urls'->>i;i=i+1;if a.id is null or url!~'^https://[A-Za-z0-9.-]+/storage/v1/object/sign/'or position('/storage/v1/object/sign/'||coalesce(a.metadata->>'bucket','director-media')||'/'||a.storage_key||'?'in url)<1 then return false;end if;end loop;return true;
exception when invalid_text_representation or numeric_value_out_of_range or invalid_parameter_value then return false;end $$;

-- New still directions are generation targets; selected frames are not.
do $$declare definition text;anchor text;begin
 anchor='if project.id is null or project.owner_id is null then return false; end if;';definition=pg_get_functiondef('public.director_document_approval_ready(uuid,text,integer)'::regprocedure);if(length(definition)-length(replace(definition,anchor,'')))/length(anchor)<>1 then raise exception'storyboard_production_approval_ready_baseline_mismatch';end if;execute replace(definition,anchor,anchor||'if left(p_logical_key,17)=''storyboard_brief:''then return public.director_storyboard_production_direction_approved(project.id,project.brief,substr(p_logical_key,18),p_version);end if;if left(p_logical_key,17)=''storyboard_frame:''then return false;end if;');
 anchor='if a.kind in(''shot_contract'',''storyboard_sequence'')';definition=pg_get_functiondef('public.director_storyboard_media_ready(uuid,uuid)'::regprocedure);if(length(definition)-length(replace(definition,anchor,'')))/length(anchor)<>1 then raise exception'storyboard_production_media_baseline_mismatch';end if;execute replace(definition,anchor,'if a.kind=''storyboard_brief''and left(a.logical_key,17)=''storyboard_brief:''then return public.director_storyboard_production_direction_approved(p.id,p.brief,substr(a.logical_key,18),a.version);end if;if a.kind=''storyboard_frame''or left(a.logical_key,17)=''storyboard_frame:''then return false;end if;'||anchor);
 anchor='if not public.director_storyboard_media_ready(p.id,a.id)then';definition=pg_get_functiondef('public.director_persist_quote(uuid,uuid,integer,uuid,text,jsonb,jsonb)'::regprocedure);if(length(definition)-length(replace(definition,anchor,'')))/length(anchor)<>1 then raise exception'storyboard_production_quote_baseline_mismatch';end if;execute replace(definition,anchor,'if a.kind=''storyboard_brief''and(not public.director_storyboard_production_quote_valid(p.id,p.brief,p_quote,p_payload,m.endpoint)or not coalesce(m.capabilities->''tasks''@>jsonb_build_array(p_quote->>''task''),false))then raise exception''storyboard_production_quote_invalid'';end if;'||anchor);
 definition=pg_get_functiondef('public.director_authorize_quote(uuid,uuid,integer,uuid,text,bigint,bigint,timestamptz)'::regprocedure);if(length(definition)-length(replace(definition,anchor,'')))/length(anchor)<>1 then raise exception'storyboard_production_authorize_baseline_mismatch';end if;execute replace(definition,anchor,'if a.kind=''storyboard_brief''and(not public.director_storyboard_production_quote_valid(p.id,p.brief,saved.quote,q.payload,m.endpoint)or not coalesce(m.capabilities->''tasks''@>jsonb_build_array(saved.quote->>''task''),false))then raise exception''storyboard_production_quote_invalid'';end if;'||anchor);
end $$;
create function public.director_storyboard_production_job_guard()returns trigger language plpgsql security invoker set search_path=''as $$
declare p public.director_projects;q public.director_proposals;a public.director_artifacts;s public.director_quote_records;m public.director_models;
begin if TG_OP='UPDATE'then if not(old.status='reserved'and new.status='submitted')then return new;end if;end if;select x.*into p from public.director_projects x where x.id=new.project_id for update;select x.*into q from public.director_proposals x where x.id=new.proposal_id and x.project_id=p.id;select x.*into a from public.director_artifacts x where x.id=q.artifact_id and x.project_id=p.id;if a.kind not in('storyboard_brief','storyboard_frame')then return new;end if;select x.*into s from public.director_quote_records x where x.proposal_id=q.id and x.project_id=p.id;select x.*into m from public.director_models x where x.id=q.model_id;if a.kind='storyboard_frame'or s.quote_id is null or not coalesce(m.capabilities->'tasks'@>jsonb_build_array(s.quote->>'task'),false)or not public.director_storyboard_production_quote_valid(p.id,p.brief,s.quote,q.payload,m.endpoint)then raise exception'storyboard_production_job_scope_changed';end if;return new;end $$;
create trigger storyboard_production_job_insert_guard before insert on public.director_jobs for each row execute function public.director_storyboard_production_job_guard();
create trigger storyboard_production_job_dispatch_guard before update of status on public.director_jobs for each row execute function public.director_storyboard_production_job_guard();
create function public.director_reserve_storyboard_job(p_actor_id uuid,p_project_id uuid,p_expected_version integer,p_quote_id text,p_authorization_id uuid,p_idempotency_key text)returns public.director_jobs language plpgsql security invoker set search_path=''as $$
declare p public.director_projects;s public.director_quote_records;q public.director_proposals;a public.director_artifacts;w public.director_work_units;j public.director_jobs;
begin select x.*into p from public.director_projects x where x.id=p_project_id for update;if p.id is null or p_actor_id is null or p.owner_id is distinct from p_actor_id then raise exception'not_project_owner';end if;select x.*into s from public.director_quote_records x where x.quote_id=p_quote_id and x.project_id=p.id and x.actor_id=p_actor_id;select x.*into q from public.director_proposals x where x.id=s.proposal_id and x.project_id=p.id;select x.*into j from public.director_jobs x where x.project_id=p.id and x.idempotency_key=p_idempotency_key;if j.id is not null then if j.proposal_id is distinct from q.id or j.authorization_id is distinct from p_authorization_id then raise exception'idempotency_conflict';end if;return j;end if;if p_expected_version is null or p.brief->'version'is distinct from to_jsonb(p_expected_version)then raise exception'storyboard_production_save_stale';end if;if s.project_version is distinct from p_expected_version or s.quote->'projectVersion'is distinct from to_jsonb(p_expected_version)then raise exception'storyboard_production_quote_stale';end if;select x.*into a from public.director_artifacts x where x.id=q.artifact_id and x.project_id=p.id and x.kind='storyboard_brief';if a.id is null then raise exception'storyboard_production_quote_invalid';end if;select x.*into w from public.director_work_units x where x.project_id=p.id and x.logical_key='storyboard:'||a.logical_key||':v'||a.version::text;if w.id is null then insert into public.director_work_units(project_id,logical_key,artifact_id)values(p.id,'storyboard:'||a.logical_key||':v'||a.version::text,a.id)returning*into w;end if;return public.director_reserve_job(p_actor_id,p.id,w.id,q.id,p_authorization_id,p_idempotency_key,q.payload_hash);end $$;
create function public.director_review_storyboard_job(p_actor_id uuid,p_project_id uuid,p_job_id uuid,p_expected_version integer,p_reason text)returns jsonb language plpgsql security invoker set search_path=''as $$
declare p public.director_projects;j public.director_jobs;q public.director_proposals;r public.director_reviews;
begin select x.*into p from public.director_projects x where x.id=p_project_id for update;if p.id is null or p_actor_id is null or p.owner_id is distinct from p_actor_id then raise exception'not_project_owner';end if;if p_expected_version is null or p.brief->'version'is distinct from to_jsonb(p_expected_version)or p_reason is null or length(btrim(p_reason))not between 5 and 2000 then raise exception'storyboard_production_review_invalid';end if;select x.*into j from public.director_jobs x where x.id=p_job_id and x.project_id=p.id;select x.*into q from public.director_proposals x where x.id=j.proposal_id and x.project_id=p.id;if j.status not in('completed','failed')or j.provider_request_id is null or not exists(select 1 from public.director_artifacts a where a.id=q.artifact_id and a.project_id=p.id and a.kind='storyboard_brief')then raise exception'storyboard_production_review_unavailable';end if;insert into public.director_reviews(project_id,job_id,actor_id,verdict,evidence)values(p.id,j.id,p_actor_id,'correction_required',jsonb_build_object('reason',p_reason,'source','explicit_user_review'))returning*into r;return jsonb_build_object('id',r.id,'projectId',p.id,'jobId',j.id,'verdict',r.verdict,'evidence',r.evidence,'createdAt',r.created_at);end $$;
do $$declare f record;begin for f in select p.oid::regprocedure signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and(p.proname like'director_storyboard_production_%'or p.proname in('director_approve_storyboard_production','director_register_storyboard_candidate','director_save_storyboard_production','director_reserve_storyboard_job','director_review_storyboard_job','director_artifact_is_current','director_composite_quote_valid','director_registry_review_ready','director_document_approval_ready','director_storyboard_media_ready','director_persist_quote','director_authorize_quote'))loop execute format('revoke all on function %s from public,anon,authenticated',f.signature);execute format('grant execute on function %s to service_role',f.signature);end loop;end $$;
comment on table public.director_storyboard_candidates is'Immutable owned stored START-state still provenance. Registration is not selection, frame review, motion/audio acceptance, finished-film approval or spending consent.';
commit;
